class TvigleIE:
    _VALID_URL = r'https?://(?:www\.)?tvigle\.ru/(?:video|show)/(?P<id>\d+)'
    _TESTS = [
        {
            'url': 'https://tvigle.ru/video/12345',
            'info_dict': {
                'id': '12345',
                'ext': 'mp4',
                'title': 'Sample Video Title',
                'description': 'Video description text',
                'age_limit': 16
            }
        }
    ]

    def __init__(self, downloader=None):
        self._downloader = downloader
        self._api_base_url = 'https://api.tvigle.ru/v3/video/'

    def _real_extract(self, url: str) -> Dict[str, Union[str, int, List[Dict]]]:
        video_id = self._match_id(url)

        webpage = self._download_webpage(url, video_id)
        video_data = self._extract_video_data(webpage, video_id)

        if not video_data:
            raise Exception(f'Unable to extract video data for {video_id}')

        formats = self._get_video_formats(video_data)
        self._sort_formats(formats)

        return {
            'id': video_id,
            'title': video_data.get('title', ''),
            'description': video_data.get('description', ''),
            'formats': formats,
            'age_limit': self._get_age_restriction(video_data),
            'ext': 'mp4'
        }

    def _match_id(self, url: str) -> str:
        mobj = re.match(self._VALID_URL, url)
        return mobj.group('id') if mobj else None

    def _download_webpage(self, url: str, video_id: str) -> str:
        try:
            request = urllib.request.Request(url)
            response = urllib.request.urlopen(request)
            return response.read().decode('utf-8')
        except Exception as e:
            raise Exception(f'Failed to download webpage: {e}')

    def _extract_video_data(self, webpage: str, video_id: str) -> Optional[Dict]:
        try:
            api_url = f'{self._api_base_url}{video_id}'
            video_data = self._download_json(api_url, video_id)
            return video_data
        except Exception as e:
            return None

    def _download_json(self, url: str, video_id: str) -> Dict:
        try:
            request = urllib.request.Request(url)
            request.add_header('Content-Type', 'application/json')
            response = urllib.request.urlopen(request)
            data = response.read().decode('utf-8')
            return json.loads(data)
        except Exception as e:
            raise Exception(f'Failed to download JSON: {e}')

    def _get_video_formats(self, video_data: Dict) -> List[Dict]:
        formats = []

        for quality_level in ['high', 'medium', 'low']:
            format_url = video_data.get(f'{quality_level}_quality_url')
            if format_url:
                formats.append({
                    'url': format_url,
                    'height': self._get_height_from_quality(quality_level),
                    'format_id': quality_level,
                    'ext': 'mp4'
                })

        return formats

    def _get_height_from_quality(self, quality_level: str) -> int:
        quality_map = {
            'high': 720,
            'medium': 480,
            'low': 360
        }
        return quality_map.get(quality_level, 360)

    def _sort_formats(self, formats: List[Dict]) -> None:
        formats.sort(key=lambda x: x.get('height', 0), reverse=True)

    def _get_age_restriction(self, video_data: Dict) -> Optional[int]:
        age_restrictions = {
            'G': 0,
            '12+': 12,
            '16+': 16,
            '18+': 18
        }

        age_rating = video_data.get('age_rating', '')
        return age_restrictions.get(age_rating)

import re
