from fractions import Fraction

class GourmetExporterPlugin:
    def __init__(self, config: Dict[str, Any] = None):
        self.config = config or {}
        self._ = gettext.gettext

    def validate_recipe_attrs(self, recipe_data: Dict[str, Any]) -> bool:
        """
        Validate recipe attributes before XML export
        """
        required_attrs = ['title', 'ingredients', 'instructions']
        return all(attr in recipe_data for attr in required_attrs)

    def seconds_to_timestring(self, total_seconds: int) -> str:
        """
        Convert seconds to human-readable time string
        """
        hours, remainder = divmod(total_seconds, 3600)
        minutes, seconds = divmod(remainder, 60)

        components = []
        if hours > 0:
            components.append(f"{hours}h")
        if minutes > 0:
            components.append(f"{minutes}m")
        if seconds > 0:
            components.append(f"{seconds}s")

        return " ".join(components) if components else "0m"

    def float_to_frac(self, value: float, max_denominator: int = 8) -> str:
        """
        Convert float to fractional representation
        """
        try:
            frac = Fraction(value).limit_denominator(max_denominator)
            return f"{frac.numerator}/{frac.denominator}" if frac.denominator > 1 else str(frac.numerator)
        except (TypeError, ValueError):
            return str(value)

class GourmetExportChecker:
    def __init__(self, exporter_plugin: GourmetExporterPlugin):
        self.exporter = exporter_plugin

    def check_rec(self, recipe_data: Dict[str, Any]) -> bool:
        """
        Comprehensive recipe validation before export
        """
        checks = [
            self._validate_title(recipe_data),
            self._validate_ingredients(recipe_data),
            self._validate_times(recipe_data)
        ]
        return all(checks)

    def _validate_title(self, recipe_data: Dict[str, Any]) -> bool:
        """
        Validate recipe title
        """
        title = recipe_data.get('title', '')
        return bool(re.match(r'^[A-Za-z0-9\s\-&]+$', title))

    def _validate_ingredients(self, recipe_data: Dict[str, Any]) -> bool:
        """
        Validate recipe ingredients
        """
        ingredients = recipe_data.get('ingredients', [])
        return len(ingredients) > 0 and all(
            re.match(r'^[\w\s]+(\d+(\.\d+)?)?[\w\s]*$', ingredient) 
            for ingredient in ingredients
        )

    def _validate_times(self, recipe_data: Dict[str, Any]) -> bool:
        """
        Validate recipe preparation and cooking times
        """
        times = {
            'prep_time': recipe_data.get('prep_time', 0),
            'cook_time': recipe_data.get('cook_time', 0)
        }
        return all(0 <= time <= 86400 for time in times.values())

def get_multiple_exporter(recipes: List[Dict[str, Any]], 
                           config: Optional[Dict[str, Any]] = None) -> List[str]:
    """
    Export multiple recipes with configurable options
    """
    plugin = GourmetExporterPlugin(config)
    export_results = []

    for recipe in recipes:
        result = do_single_export(recipe, plugin)
        if result:
            export_results.append(result)

    return export_results

def do_single_export(recipe: Dict[str, Any], 
                     plugin: GourmetExporterPlugin,
                     multiplier: float = 1.0) -> Optional[str]:
    """
    Single recipe export with optional scaling
    """
    checker = GourmetExportChecker(plugin)

    if not checker.check_rec(recipe):
        return None

    # XML generation logic would be implemented here
    # This is a placeholder representation
    xml_content = f"""
    <recipe>
        <title>{recipe.get('title', '')}</title>
        <ingredients>
            {' '.join(recipe.get('ingredients', []))}
        </ingredients>
    </recipe>
    """

    return xml_content

class PortReservation(A10BaseClass):
    def __init__(self, **kwargs):
        self.discriminator = None
        self.inside = None
        self.tunnel_dest_address = None
        self.inside_addr = None
        self.nat = None

        # Optional port-related parameters
        self.port_start = kwargs.get('port_start', None)
        self.port_end = kwargs.get('port_end', None)

        # Validate and set mandatory parameters
        self._validate_config(kwargs)

        # Dynamic attribute assignment
        for key, value in kwargs.items():
            if hasattr(self, key):
                setattr(self, key, value)

    def _validate_config(self, config):
        """
        Validate configuration parameters
        """
        mandatory_params = ['inside', 'tunnel_dest_address']
        for param in mandatory_params:
            if param not in config:
                raise ValueError(f"Missing mandatory parameter: {param}")

        # Validate port range if specified
        if self.port_start is not None and self.port_end is not None:
            if not (0 <= self.port_start <= 65535 and 0 <= self.port_end <= 65535):
                raise ValueError("Port range must be between 0 and 65535")

            if self.port_start > self.port_end:
                raise ValueError("Port start must be less than or equal to port end")

    def get_reservation_key(self):
        """
        Generate a unique key for port reservation
        """
        key_components = [
            str(self.inside),
            str(self.tunnel_dest_address),
            str(self.port_start),
            str(self.port_end)
        ]
        return ":".join(filter(None, key_components))

    def validate_network_addresses(self):
        """
        Validate IPv4 and IPv6 network addresses
        """
        # Implement address validation logic
        if self.inside and not self._is_valid_ip(self.inside):
            raise ValueError("Invalid inside network address")

        if self.tunnel_dest_address and not self._is_valid_ip(self.tunnel_dest_address):
            raise ValueError("Invalid tunnel destination address")

    def _is_valid_ip(self, address):
        """
        Check if IP address is valid
        """
        try:
            # Validate both IPv4 and IPv6 addresses
            import ipaddress
            ipaddress.ip_address(address)
            return True
        except ValueError:
            return False

    def serialize(self):
        """
        Serialize port reservation configuration
        """
        return {
            'inside': self.inside,
            'tunnel_dest_address': self.tunnel_dest_address,
            'port_start': self.port_start,
            'port_end': self.port_end
        }

import pygame
import os
from game_module import load_image, load_sprites, flip_sprites, load_sprite

class Resources:
    def __init__(self, base_path='assets'):
        pygame.init()
        self.base_path = base_path
        self.player = {}
        self.tiles = {}
        self.imagen = {}
        self._load_player_sprites()
        self._load_tile_sprites()

    def _load_player_sprites(self):
        player_path = os.path.join(self.base_path, 'player')

        # Idle sprites
        self.player['quieto_der'] = load_sprites(
            os.path.join(player_path, 'idle_right.png'), 
            sprite_width=64, 
            sprite_height=64, 
            frame_count=4
        )
        self.player['quieto_izq'] = flip_sprites(self.player['quieto_der'])

        # Walking sprites
        self.player['caminando_der'] = load_sprites(
            os.path.join(player_path, 'walk_right.png'), 
            sprite_width=64, 
            sprite_height=64, 
            frame_count=6
        )
        self.player['caminando_izq'] = flip_sprites(self.player['caminando_der'])

        # Jumping sprites
        self.player['saltando_der'] = load_sprites(
            os.path.join(player_path, 'jump_right.png'), 
            sprite_width=64, 
            sprite_height=64, 
            frame_count=2
        )
        self.player['saltando_izq'] = flip_sprites(self.player['saltando_der'])

    def _load_tile_sprites(self):
        tiles_path = os.path.join(self.base_path, 'tiles')

        # Ground tiles
        self.tiles['ground'] = load_sprite(
            os.path.join(tiles_path, 'ground.png')
        )

        # Platform tiles
        self.tiles['platform'] = load_sprite(
            os.path.join(tiles_path, 'platform.png')
        )

        # Background elements
        self.tiles['background_rock'] = load_sprite(
            os.path.join(tiles_path, 'rock.png')
        )

    def get_player_sprite(self, state, direction):
        key = f'{state}_{direction}'
        return self.player.get(key, [])

    def get_tile_sprite(self, tile_type):
        return self.tiles.get(tile_type)

    def preload_backgrounds(self):
        backgrounds_path = os.path.join(self.base_path, 'backgrounds')

        self.imagen['level1'] = load_image(
            os.path.join(backgrounds_path, 'level1_background.png')
        )

        self.imagen['level2'] = load_image(
            os.path.join(backgrounds_path, 'level2_background.png')
        )

    def cleanup(self):
        pygame.quit()

def main():
    resources = Resources()
    resources.preload_backgrounds()
    # Additional game initialization logic
    resources.cleanup()

if __name__ == "__main__":
    main()

import functools
from urllib.parse import urlparse, urlunparse

from django.conf import settings
from django.contrib.auth import REDIRECT_FIELD_NAME
from django.contrib.auth.decorators import user_passes_test
from django.core.exceptions import PermissionDenied
from django.shortcuts import resolve_url, redirect

def login_required(function=None, redirect_field_name=REDIRECT_FIELD_NAME, login_url=None):
    """
    Decorator for views that checks that the user is logged in, redirecting
    to the log-in page if necessary.
    """
    actual_decorator = user_passes_test(
        lambda u: u.is_authenticated,
        login_url=login_url,
        redirect_field_name=redirect_field_name
    )

    if function:
        return actual_decorator(function)
    return actual_decorator

def permission_required(permission, login_url=None, raise_exception=False):
    """
    Decorator for views that checks if a user has a specific permission.
    """
    def decorator(view_func):
        @functools.wraps(view_func)
        def wrapper(request, *args, **kwargs):
            if request.user.has_perm(permission):
                return view_func(request, *args, **kwargs)

            if raise_exception:
                raise PermissionDenied

            return redirect_to_login(request.get_full_path(), login_url)
        return wrapper
    return decorator

def redirect_to_login(next_page=None, login_url=None, redirect_field_name=REDIRECT_FIELD_NAME):
    """
    Redirects the user to the login page with the next page parameter.
    """
    login_url = login_url or settings.LOGIN_URL
    login_url = resolve_url(login_url)

    if next_page is None:
        next_page = ''

    login_url_parts = list(urlparse(login_url))

    if redirect_field_name:
        query_params = login_url_parts[4]
        query_list = dict([part.split('=') for part in query_params.split('&') if part])
        query_list[redirect_field_name] = next_page
        login_url_parts[4] = '&'.join([f"{k}={v}" for k, v in query_list.items()])

    return redirect(urlunparse(login_url_parts))

def user_has_group_permission(group_name):
    """
    Decorator to check if user belongs to a specific group.
    """
    def decorator(view_func):
        @functools.wraps(view_func)
        def wrapper(request, *args, **kwargs):
            if request.user.groups.filter(name=group_name).exists():
                return view_func(request, *args, **kwargs)

            if request.user.is_authenticated:
                raise PermissionDenied

            return redirect_to_login(request.get_full_path())
        return wrapper
    return decorator

def superuser_required(function=None, login_url=None):
    """
    Decorator that checks if the user is a superuser.
    """
    actual_decorator = user_passes_test(
        lambda u: u.is_superuser,
        login_url=login_url
    )

    if function:
        return actual_decorator(function)
    return actual_decorator

def staff_member_required(function=None, login_url=None):
    """
    Decorator that checks if the user is a staff member.
    """
    actual_decorator = user_passes_test(
        lambda u: u.is_staff,
        login_url=login_url
    )

    if function:
        return actual_decorator(function)
    return actual_decorator

import logging
import requests
from typing import Dict, List, Optional
from pajbot.apiwrappers import BaseAPI
from pajbot.models.emote import Emote
from redis import Redis
import json

class TwitchKrakenV5API:
    def __init__(self, client_id: str, oauth_token: str, redis_client: Redis = None):
        self.client_id = client_id
        self.oauth_token = oauth_token
        self.redis = redis_client or Redis()
        self.base_url = 'https://api.twitch.tv/kraken'
        self.logger = logging.getLogger(__name__)

    def _get_headers(self) -> Dict[str, str]:
        return {
            'Accept': 'application/vnd.twitchtv.v5+json',
            'Client-ID': self.client_id,
            'Authorization': f'OAuth {self.oauth_token}'
        }

    def get_stream_status(self, channel_id: str) -> Optional[Dict]:
        cache_key = f'twitch:stream_status:{channel_id}'
        cached_status = self.redis.get(cache_key)

        if cached_status:
            return json.loads(cached_status)

        try:
            response = requests.get(
                f'{self.base_url}/streams/{channel_id}',
                headers=self._get_headers()
            )
            response.raise_for_status()
            stream_data = response.json().get('stream')

            if stream_data:
                self.redis.setex(cache_key, 60, json.dumps(stream_data))
                return stream_data
            return None

        except requests.RequestException as e:
            self.logger.error(f'Stream status error: {e}')
            return None

    def set_game(self, channel_id: str, game_name: str) -> bool:
        try:
            response = requests.put(
                f'{self.base_url}/channels/{channel_id}',
                headers=self._get_headers(),
                json={'channel': {'game': game_name}}
            )
            return response.status_code == 200
        except requests.RequestException as e:
            self.logger.error(f'Set game error: {e}')
            return False

    def set_title(self, channel_id: str, stream_title: str) -> bool:
        try:
            response = requests.put(
                f'{self.base_url}/channels/{channel_id}',
                headers=self._get_headers(),
                json={'channel': {'status': stream_title}}
            )
            return response.status_code == 200
        except requests.RequestException as e:
            self.logger.error(f'Set title error: {e}')
            return False

    def get_vod_videos(self, channel_id: str, limit: int = 10) -> List[Dict]:
        cache_key = f'twitch:vods:{channel_id}'
        cached_vods = self.redis.get(cache_key)

        if cached_vods:
            return json.loads(cached_vods)

        try:
            response = requests.get(
                f'{self.base_url}/channels/{channel_id}/videos',
                headers=self._get_headers(),
                params={'limit': limit}
            )
            response.raise_for_status()
            vods = response.json().get('videos', [])

            self.redis.setex(cache_key, 3600, json.dumps(vods))
            return vods

        except requests.RequestException as e:
            self.logger.error(f'VOD fetch error: {e}')
            return []

    def fetch_global_emotes(self) -> List[Emote]:
        cache_key = 'twitch:global_emotes'
        cached_emotes = self.redis.get(cache_key)

        if cached_emotes:
            return [Emote(**emote) for emote in json.loads(cached_emotes)]

        try:
            response = requests.get(
                f'{self.base_url}/emoticons',
                headers=self._get_headers()
            )
            response.raise_for_status()
            emote_data = response.json().get('emoticons', [])

            global_emotes = [
                Emote(
                    code=emote['regex'],
                    provider='twitch',
                    id=emote.get('id')
                ) for emote in emote_data
            ]

            self.redis.setex(cache_key, 86400, json.dumps([
                emote.__dict__ for emote in global_emotes
            ]))

            return global_emotes

        except requests.RequestException as e:
            self.logger.error(f'Global emotes fetch error: {e}')
            return []

    def get_global_emotes(self) -> List[Emote]:
        return self.fetch_global_emotes()

import unittest
from datetime import datetime, timedelta
import iso8601

class VersionCheckUtility:
    def __init__(self, supported_versions=None):
        self._supported_versions = supported_versions or []
        self._last_version_check_time = None
        self._version_check_interval = timedelta(hours=24)

    def _parse_version(self, version_str):
        """Parse semantic version string into comparable components."""
        try:
            parts = version_str.split('.')
            major = int(parts[0]) if parts else 0
            minor = int(parts[1]) if len(parts) > 1 else 0
            patch = int(parts[2].split('-')[0]) if len(parts) > 2 else 0
            prerelease = parts[2].split('-')[1] if len(parts) > 2 and '-' in parts[2] else None
            return (major, minor, patch, prerelease)
        except (ValueError, IndexError):
            return (0, 0, 0, None)

    def _is_version_supported(self, version):
        """Check if version is supported."""
        return version in self._supported_versions

    def _is_later_version_available(self, current_version, latest_version):
        """Compare versions semantically."""
        current = self._parse_version(current_version)
        latest = self._parse_version(latest_version)

        # Compare major, minor, patch versions
        for c, l in zip(current[:3], latest[:3]):
            if l > c:
                return True
            elif l < c:
                return False

        # If numeric parts are equal, compare pre-release
        if current[3] is None and latest[3] is not None:
            return False
        elif current[3] is not None and latest[3] is None:
            return True

        return False

    def get_last_version_check_time(self):
        """Retrieve last version check timestamp."""
        return self._last_version_check_time

    def set_last_version_check_time(self, timestamp=None):
        """Set last version check timestamp."""
        self._last_version_check_time = timestamp or datetime.utcnow()

    def is_version_check_needed(self):
        """Determine if version check is required."""
        if self._last_version_check_time is None:
            return True

        current_time = datetime.utcnow()
        time_since_last_check = current_time - self._last_version_check_time
        return time_since_last_check >= self._version_check_interval

class CLIConfig:
    def __init__(self, current_version='1.0.0'):
        self.current_version = current_version
        self.version_checker = VersionCheckUtility([
            '1.0.0', '1.1.0', '1.2.0', '2.0.0'
        ])

    def check_version_compatibility(self, latest_version):
        """Check version compatibility and availability."""
        is_supported = self.version_checker._is_version_supported(latest_version)
        is_update_available = self.version_checker._is_later_version_available(
            self.current_version, latest_version
        )
        return is_supported, is_update_available

class TestVersionCheck(unittest.TestCase):
    def setUp(self):
        self.version_utility = VersionCheckUtility(['1.0.0', '1.1.0', '2.0.0'])

    def test_version_parsing(self):
        self.assertEqual(
            self.version_utility._parse_version('1.2.3'), 
            (1, 2, 3, None)
        )
        self.assertEqual(
            self.version_utility._parse_version('1.2.3-alpha'), 
            (1, 2, 3, 'alpha')
        )

    def test_version_support(self):
        self.assertTrue(self.version_utility._is_version_supported('1.0.0'))
        self.assertFalse(self.version_utility._is_version_supported('3.0.0'))

    def test_version_comparison(self):
        self.assertTrue(
            self.version_utility._is_later_version_available('1.0.0', '1.1.0')
        )
        self.assertTrue(
            self.version_utility._is_later_version_available('1.1.0', '2.0.0')
        )
        self.assertFalse(
            self.version_utility._is_later_version_available('2.0.0', '1.1.0')
        )

    def test_version_check_interval(self):
        self.version_utility.set_last_version_check_time()
        self.assertFalse(self.version_utility.is_version_check_needed())

def main():
    config = CLIConfig()
    latest_version = '1.2.0'
    is_supported, is_update_available = config.check_version_compatibility(latest_version)

    print(f"Current Version: {config.current_version}")
    print(f"Latest Version: {latest_version}")
    print(f"Supported: {is_supported}")
    print(f"Update Available: {is_update_available}")

if __name__ == '__main__':
    main()

from oslo_versionedobjects import base as obj_base
from oslo_versionedobjects import fields as obj_fields
from knob.db.sqlalchemy import api as db_api
from knob.objects import base
from knob.objects import fields

@obj_base.VersionedObjectRegistry.register
class Service(base.KnobObject, base.VersionedObjectDictCompat):
    """Representation of a Service entity."""

    VERSION = '1.0'

    fields = {
        'id': obj_fields.IntegerField(nullable=False),
        'host': obj_fields.StringField(nullable=False),
        'binary': obj_fields.StringField(nullable=False),
        'topic': obj_fields.StringField(nullable=True),
        'created_at': obj_fields.DateTimeField(nullable=True),
        'updated_at': obj_fields.DateTimeField(nullable=True),
        'deleted_at': obj_fields.DateTimeField(nullable=True),
        'deleted': obj_fields.BooleanField(default=False)
    }

    @classmethod
    def get_by_id(cls, context, service_id):
        """Retrieve a service by its ID."""
        db_service = db_api.service_get_by_id(context, service_id)
        return cls._from_db_object(context, cls(), db_service)

    @classmethod
    def create(cls, context, values):
        """Create a new service record."""
        db_service = db_api.service_create(context, values)
        return cls._from_db_object(context, cls(), db_service)

    @classmethod
    def update_by_id(cls, context, service_id, values):
        """Update an existing service record."""
        db_service = db_api.service_update(context, service_id, values)
        return cls._from_db_object(context, cls(), db_service)

    def delete(self, context):
        """Delete a service record (soft delete)."""
        db_api.service_delete(context, self.id)
        self.deleted_at = fields.field_types.BaseDateTime.get_now()
        self.deleted = True

    @classmethod
    def get_all(cls, context, filters=None, limit=None, marker=None):
        """Retrieve all service records with optional filtering."""
        db_services = db_api.service_get_all(
            context, filters=filters, limit=limit, marker=marker
        )
        return cls._from_db_objects(context, db_services)

    @classmethod
    def get_all_by_args(cls, context, **kwargs):
        """Retrieve service records based on specific arguments."""
        db_services = db_api.service_get_all_by_args(context, **kwargs)
        return cls._from_db_objects(context, db_services)

    @classmethod
    def _from_db_object(cls, context, obj, db_obj):
        """Convert database object to Service object."""
        for field in cls.fields:
            if hasattr(db_obj, field):
                setattr(obj, field, getattr(db_obj, field))
        obj._context = context
        obj.obj_reset_changes()
        return obj

    @classmethod
    def _from_db_objects(cls, context, db_objects):
        """Convert multiple database objects to Service objects."""
        return [cls._from_db_object(context, cls(), obj) for obj in db_objects]

    def obj_make_compatible(self, primitive, target_version):
        """Ensure compatibility across object versions."""
        super().obj_make_compatible(primitive, target_version)

    def obj_load_attr(self, attrname):
        """Load an attribute if not already present."""
        if attrname not in self.obj_loaded_attrs:
            self.refresh(self._context)

import re
from mrjob.job import MRJob
from mrjob.step import MRStep
import email
from datetime import datetime
import hashlib

class MRMultilineInput(MRJob):
    def configure_args(self):
        super(MRMultilineInput, self).configure_args()
        self.add_file_arg('--stopwords', help='Path to stopwords file')

    def mapper_init_count(self):
        self.current_message = {}
        self.current_body = []
        self.in_message = False

    def mapper_count(self, _, line):
        line = line.strip()

        if line.startswith('Message-ID:'):
            if self.current_message:
                yield self.current_message.get('message_id', ''), self.current_message
            self.current_message = {}
            self.current_body = []
            self.in_message = True
            self.current_message['message_id'] = self.get_id_from_line(line)

        if not self.in_message:
            return

        if line.startswith('Date:'):
            self.current_message['date'] = self.parse_date(line)

        if line.startswith('From:'):
            self.current_message['sender'] = self.clean_values(line)

        if line.startswith('Subject:'):
            self.current_message['subject'] = self.clean_values(line)

        if line.startswith('In-Reply-To:'):
            self.current_message['parent_id'] = self.get_id_from_line(line)

        if line.startswith('References:'):
            refs = re.findall(r'<[^>]+>', line)
            if refs:
                self.current_message['references'] = refs

        self.current_body.append(line)

        if line == '':
            self.current_message['body'] = ' '.join(self.current_body)

    def mapper_child(self, message_id, message):
        # Determine message relationships
        if 'parent_id' in message:
            message['type'] = 'reply'
            yield message['parent_id'], message
        elif 'references' in message:
            message['type'] = 'thread'
            for ref in message['references']:
                yield ref.strip('<>'), message
        else:
            message['type'] = 'original'
            yield message_id, message

    def reducer_aggregate(self, key, messages):
        # Group and organize messages by relationships
        sorted_messages = sorted(messages, key=lambda x: x.get('date', ''))

        conversation = {
            'key': key,
            'thread': sorted_messages,
            'total_messages': len(sorted_messages)
        }

        yield key, conversation

    def get_id_from_line(self, line):
        # Extract unique message identifier
        match = re.search(r'<([^>]+)>', line)
        return match.group(1) if match else hashlib.md5(line.encode()).hexdigest()

    def clean_values(self, line):
        # Clean and normalize metadata values
        return re.sub(r'^[^:]+:\s*', '', line).strip()

    def parse_date(self, line):
        # Parse and standardize date formats
        try:
            date_str = re.sub(r'^Date:\s*', '', line)
            return datetime.strptime(date_str, '%a, %d %b %Y %H:%M:%S %z')
        except ValueError:
            return None

    def steps(self):
        return [
            MRStep(mapper_init=self.mapper_init_count,
                   mapper=self.mapper_count,
                   reducer=self.reducer_aggregate),
            MRStep(mapper=self.mapper_child)
        ]

if __name__ == '__main__':
    MRMultilineInput.run()

import asyncio
import logging
import json
import aioredis
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse

class URLExtractionConsumer:
    def __init__(self, redis_host='localhost', redis_port=6379, queue_name='html_queue'):
        self.redis_host = redis_host
        self.redis_port = redis_port
        self.queue_name = queue_name
        self.redis_pool = None
        self._log = logging.getLogger(self.__class__.__name__)
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s: %(message)s')

    async def _connect_redis(self):
        try:
            self.redis_pool = await aioredis.create_redis_pool(
                f'redis://{self.redis_host}:{self.redis_port}',
                minsize=5,
                maxsize=10
            )
            self._log.info(f"Connected to Redis at {self.redis_host}:{self.redis_port}")
        except Exception as e:
            self._log.error(f"Redis connection error: {e}")
            raise

    async def _scrape_urls_from_queued_html(self, html_payload, base_url):
        try:
            soup = BeautifulSoup(html_payload, 'html.parser')
            extracted_urls = []

            for link in soup.find_all('a', href=True):
                href = link['href']
                absolute_url = urljoin(base_url, href)

                if urlparse(absolute_url).scheme in ['http', 'https']:
                    extracted_urls.append({
                        'url': absolute_url,
                        'anchor_text': link.get_text().strip()
                    })

            return extracted_urls

        except Exception as e:
            self._log.error(f"URL extraction error: {e}")
            return []

    async def _scrape_urls(self):
        if not self.redis_pool:
            await self._connect_redis()

        while True:
            try:
                html_payload_data = await self.redis_pool.blpop(self.queue_name)

                if html_payload_data:
                    _, html_payload = html_payload_data
                    payload_json = json.loads(html_payload.decode('utf-8'))

                    base_url = payload_json.get('base_url', '')
                    html_content = payload_json.get('html_content', '')

                    extracted_urls = await self._scrape_urls_from_queued_html(html_content, base_url)

                    if extracted_urls:
                        output_data = {
                            'source_url': base_url,
                            'extracted_urls': extracted_urls
                        }
                        print(json.dumps(output_data, indent=2))
                        self._log.info(f"Extracted {len(extracted_urls)} URLs from {base_url}")

            except asyncio.CancelledError:
                break
            except Exception as e:
                self._log.error(f"Processing error: {e}")
                await asyncio.sleep(5)

    async def main(self):
        try:
            await self._connect_redis()
            self._log.info("Starting URL extraction consumer...")
            await self._scrape_urls()
        except Exception as e:
            self._log.error(f"Main process error: {e}")
        finally:
            if self.redis_pool:
                self.redis_pool.close()
                await self.redis_pool.wait_closed()

if __name__ == "__main__":
    consumer = URLExtractionConsumer()
    asyncio.run(consumer.main())

import os
import hashlib
import base64
import uuid
import requests
from io import BytesIO
from PIL import Image
from typing import Optional, Union, Dict, Any

class ThumbnailSettings:
    CACHE_DIR = os.path.join(os.path.dirname(__file__), 'thumbnail_cache')
    DEFAULT_FORMAT = 'png'
    DEFAULT_QUALITY = 85
    MAX_CACHE_SIZE = 500 * 1024 * 1024  # 500 MB

class CacheBackend:
    @staticmethod
    def generate_cache_key(source: str, width: int, height: int, crop: bool = False) -> str:
        hash_input = f"{source}_{width}x{height}_{crop}"
        return hashlib.md5(hash_input.encode()).hexdigest()

    @staticmethod
    def get_cache_path(cache_key: str, format: str = 'png') -> str:
        return os.path.join(ThumbnailSettings.CACHE_DIR, f"{cache_key}.{format}")

class ImageEngine:
    @staticmethod
    def resize_image(image: Image.Image, width: int, height: int, crop: bool = False) -> Image.Image:
        if crop:
            return ImageEngine._crop_thumbnail(image, width, height)
        return ImageEngine._resize_thumbnail(image, width, height)

    @staticmethod
    def _crop_thumbnail(image: Image.Image, width: int, height: int) -> Image.Image:
        aspect_ratio = image.width / image.height
        target_ratio = width / height

        if aspect_ratio > target_ratio:
            new_height = height
            new_width = int(new_height * aspect_ratio)
        else:
            new_width = width
            new_height = int(new_width / aspect_ratio)

        resized_image = image.resize((new_width, new_height), Image.LANCZOS)
        left = (resized_image.width - width) // 2
        top = (resized_image.height - height) // 2

        return resized_image.crop((left, top, left + width, top + height))

    @staticmethod
    def _resize_thumbnail(image: Image.Image, width: int, height: int) -> Image.Image:
        image.thumbnail((width, height), Image.LANCZOS)
        return image

class ThumbnailGenerator:
    @staticmethod
    def get_thumbnail(
        source: Union[str, bytes], 
        width: int, 
        height: int, 
        crop: bool = False, 
        force_generate: bool = False
    ) -> str:
        # Resolve image source
        if isinstance(source, bytes):
            image = Image.open(BytesIO(source))
        elif source.startswith('http'):
            response = requests.get(source)
            image = Image.open(BytesIO(response.content))
        else:
            image = Image.open(source)

        # Generate cache key
        cache_key = CacheBackend.generate_cache_key(
            str(source), width, height, crop
        )
        cache_path = CacheBackend.get_cache_path(cache_key)

        # Check cache
        if not force_generate and os.path.exists(cache_path):
            return cache_path

        # Ensure cache directory exists
        os.makedirs(ThumbnailSettings.CACHE_DIR, exist_ok=True)

        # Process image
        processed_image = ImageEngine.resize_image(image, width, height, crop)
        processed_image.save(
            cache_path, 
            format=ThumbnailSettings.DEFAULT_FORMAT, 
            quality=ThumbnailSettings.DEFAULT_QUALITY
        )

        return cache_path

def main():
    # Example usage
    thumbnail = ThumbnailGenerator.get_thumbnail(
        'image.jpg', 
        width=200, 
        height=200, 
        crop=True
    )
    print(f"Generated thumbnail: {thumbnail}")

if __name__ == "__main__":
    main()

import unittest
import re
import sqlite3

class TVShow(object):
    def __init__(self, name, release, season_regex=None):
        self.name = name
        self.release = release
        self.curRegex = season_regex

class DatabaseManager:
    def __init__(self, db_path):
        self.db_path = db_path
        self.connection = None
        self.cursor = None

    def connect(self):
        try:
            self.connection = sqlite3.connect(self.db_path)
            self.cursor = self.connection.cursor()
        except sqlite3.Error as e:
            print(f"Database connection error: {e}")
            raise

    def close(self):
        if self.connection:
            self.connection.close()

    def loadShowsFromDB(self):
        shows = []
        try:
            self.connect()
            self.cursor.execute("SELECT show_name, release_name, season_regex FROM shows")
            results = self.cursor.fetchall()

            for row in results:
                show = TVShow(row[0], row[1], row[2])
                shows.append(show)

        except sqlite3.Error as e:
            print(f"Error loading shows: {e}")
        finally:
            self.close()

        return shows

class XEMBasicTests(unittest.TestCase):
    def setUp(self):
        self.db_manager = DatabaseManager('shows.db')
        self.shows = self.db_manager.loadShowsFromDB()

    def test_show_name_formatting(self):
        for show in self.shows:
            # Basic show name validation
            self.assertIsNotNone(show.name, "Show name cannot be empty")
            self.assertTrue(len(show.name) > 2, "Show name too short")
            self.assertFalse(re.search(r'[^\w\s-]', show.name), "Invalid characters in show name")

    def test_season_regex_matching(self):
        for show in self.shows:
            if show.curRegex:
                try:
                    compiled_regex = re.compile(show.curRegex)
                    self.assertTrue(compiled_regex.search(show.release), 
                                    f"Release {show.release} does not match regex {show.curRegex}")
                except re.error as e:
                    self.fail(f"Invalid regex for show {show.name}: {e}")

    def test_release_name_conventions(self):
        valid_release_patterns = [
            r'^[A-Za-z0-9\.\-\_]+S\d{2}E\d{2}',
            r'^[A-Za-z0-9\.\-\_]+\d{4}x\d{2}',
        ]

        for show in self.shows:
            match_found = any(re.match(pattern, show.release) for pattern in valid_release_patterns)
            self.assertTrue(match_found, f"Release {show.release} does not follow naming conventions")

    def test_database_integrity(self):
        duplicates = {}
        for show in self.shows:
            if show.name in duplicates:
                duplicates[show.name].append(show.release)
            else:
                duplicates[show.name] = [show.release]

        for name, releases in duplicates.items():
            self.assertEqual(len(releases), len(set(releases)), 
                             f"Duplicate releases found for show {name}")

def main():
    unittest.main()

if __name__ == '__main__':
    main()

import math

def round_sig_fig(x, n):
    """
    Round a number to a specified number of significant figures.

    Args:
        x (float): Number to round
        n (int): Number of significant figures

    Returns:
        float: Rounded number
    """
    if x == 0:
        return 0

    try:
        magnitude = math.floor(math.log10(abs(x)))
        factor = 10 ** (magnitude - n + 1)
        return round(x / factor) * factor
    except (ValueError, OverflowError):
        return x

def format_scientific(x, n):
    """
    Convert number to scientific notation with specified significant figures.

    Args:
        x (float): Number to format
        n (int): Number of significant figures

    Returns:
        str: Scientific notation representation
    """
    if x == 0:
        return "0.{}e+00".format("0" * (n - 1))

    try:
        magnitude = math.floor(math.log10(abs(x)))
        normalized = x / (10 ** magnitude)
        rounded = round_sig_fig(normalized, n)

        scientific_str = "{:.{}f}e{:+03d}".format(
            rounded, 
            max(0, n - 1), 
            magnitude
        )
        return scientific_str
    except (ValueError, OverflowError):
        return str(x)

def format_general(x, n):
    """
    Convert number to general notation with specified significant figures.

    Args:
        x (float): Number to format
        n (int): Number of significant figures

    Returns:
        str: General notation representation
    """
    if x == 0:
        return "0.{}".format("0" * (n - 1))

    try:
        magnitude = math.floor(math.log10(abs(x)))

        if -2 <= magnitude < n:
            # Standard decimal representation
            rounded = round_sig_fig(x, n)
            decimal_places = max(0, n - magnitude - 1)
            return "{:.{}f}".format(rounded, decimal_places)
        else:
            # Scientific notation
            return format_scientific(x, n)
    except (ValueError, OverflowError):
        return str(x)

def validate_input(x, n):
    """
    Validate input parameters for rounding and formatting.

    Args:
        x (float): Number to validate
        n (int): Number of significant figures

    Raises:
        ValueError: If inputs are invalid
    """
    if not isinstance(x, (int, float)):
        raise ValueError("Input must be a numeric value")

    if not isinstance(n, int) or n < 1:
        raise ValueError("Significant figures must be a positive integer")

def process_number(x, n, formatter='general'):
    """
    Process and format a number with specified parameters.

    Args:
        x (float): Number to process
        n (int): Number of significant figures
        formatter (str): Formatting method

    Returns:
        Formatted number representation
    """
    validate_input(x, n)

    if formatter == 'scientific':
        return format_scientific(x, n)
    elif formatter == 'general':
        return format_general(x, n)
    elif formatter == 'round':
        return round_sig_fig(x, n)
    else:
        raise ValueError("Invalid formatting method")

def compare_representations():
    """
    Demonstrate number representation techniques.
    """
    test_numbers = [
        0.0001234,
        12345.6789,
        0.00000789,
        1_000_000.123,
        -42.987654
    ]

    sig_figs = [3, 4, 5]

    for number in test_numbers:
        print(f"Number: {number}")
        for sig_fig in sig_figs:
            print(f"  {sig_fig} Sig Figs:")
            print(f"    Scientific: {process_number(number, sig_fig, 'scientific')}")
            print(f"    General:    {process_number(number, sig_fig, 'general')}")
            print(f"    Rounded:    {process_number(number, sig_fig, 'round')}")

if __name__ == "__main__":
    compare_representations()

from django.db import models
from django.utils import timezone
from django.conf import settings
from django.urls import reverse
from django.contrib.sites.models import Site
from parler.models import TranslatableModel, TranslatedFields
from parler.managers import TranslatableManager

class EntryQuerySet(models.QuerySet):
    def live(self):
        return self.filter(
            status=Entry.STATUS_LIVE,
            pub_date__lte=timezone.now()
        )

    def published_on_site(self, site=None):
        site = site or Site.objects.get_current()
        return self.live().filter(sites=site)

class EntryManager(TranslatableManager):
    def get_queryset(self):
        return EntryQuerySet(self.model, using=self._db)

    def live(self):
        return self.get_queryset().live()

    def published_on_site(self, site=None):
        return self.get_queryset().published_on_site(site)

class Entry(TranslatableModel):
    STATUS_DRAFT = 'draft'
    STATUS_LIVE = 'live'
    STATUS_CHOICES = [
        (STATUS_DRAFT, 'Draft'),
        (STATUS_LIVE, 'Live'),
    ]

    author = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.SET_NULL,
        null=True,
        related_name='press_entries'
    )

    translations = TranslatedFields(
        title=models.CharField(max_length=255),
        subtitle=models.CharField(max_length=255, blank=True),
        content=models.TextField(),
        excerpt=models.TextField(blank=True)
    )

    slug = models.SlugField(unique=True)
    pub_date = models.DateTimeField(default=timezone.now)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)
    status = models.CharField(
        max_length=10,
        choices=STATUS_CHOICES,
        default=STATUS_DRAFT
    )

    sites = models.ManyToManyField(Site, related_name='press_entries', blank=True)

    objects = EntryManager()

    class Meta:
        verbose_name_plural = 'Press Entries'
        ordering = ['-pub_date']

    def __str__(self):
        return self.title

    def get_absolute_url(self):
        return reverse('press_entry_detail', kwargs={'slug': self.slug})

class Link(TranslatableModel):
    entry = models.ForeignKey(
        Entry,
        on_delete=models.CASCADE,
        related_name='links'
    )

    translations = TranslatedFields(
        title=models.CharField(max_length=255),
        description=models.TextField(blank=True)
    )

    url = models.URLField(max_length=500)
    is_primary = models.BooleanField(default=False)
    created_at = models.DateTimeField(auto_now_add=True)

    def __str__(self):
        return self.title

    class Meta:
        unique_together = ['entry', 'is_primary']
        ordering = ['-created_at']

import sys
import pdb
import ipdb
import functools
import traceback
import threading
import contextlib
from typing import Dict, Any, Callable, Optional

class Tdb:
    """Advanced Tracing Debugger for Fine-Grained Function Monitoring"""

    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if not cls._instance:
            with cls._lock:
                if not cls._instance:
                    cls._instance = super(Tdb, cls).__new__(cls)
        return cls._instance

    def __init__(self):
        self.codemap: Dict[str, Any] = {}
        self.active_traces: Dict[str, bool] = {}
        self.global_trace_enabled = False

    def add_trace(self, func_name: str, trace_level: int = 1):
        """Add tracing for specific function"""
        self.active_traces[func_name] = True

    def remove_trace(self, func_name: str):
        """Remove tracing for specific function"""
        self.active_traces.pop(func_name, None)

    def trace_dispatch(self, frame, event, arg):
        """Custom trace dispatch mechanism"""
        func_name = frame.f_code.co_name

        if func_name in self.active_traces or self.global_trace_enabled:
            self._handle_trace_event(frame, event, arg)

        return self.trace_dispatch

    def _handle_trace_event(self, frame, event, arg):
        """Internal trace event processing"""
        if event == 'call':
            self.dispatch_call(frame)
        elif event == 'return':
            self.dispatch_return(frame, arg)
        elif event == 'exception':
            self.dispatch_exception(frame, arg)

    def dispatch_call(self, frame):
        """Handle function call tracing"""
        filename = frame.f_code.co_filename
        lineno = frame.f_lineno
        func_name = frame.f_code.co_name

        trace_info = {
            'filename': filename,
            'lineno': lineno,
            'function': func_name,
            'locals': frame.f_locals
        }

        self.codemap[func_name] = trace_info

    def dispatch_return(self, frame, return_value):
        """Handle function return tracing"""
        pass

    def dispatch_exception(self, frame, exception):
        """Handle exception tracing"""
        traceback.print_exc()

    def set_trace(self, enable: bool = True):
        """Global trace control"""
        self.global_trace_enabled = enable
        sys.settrace(self.trace_dispatch if enable else None)

    @contextlib.contextmanager
    def with_trace(self, func_names: Optional[list] = None):
        """Context manager for tracing"""
        try:
            if func_names:
                for name in func_names:
                    self.add_trace(name)

            self.set_trace(True)
            yield

        finally:
            self.set_trace(False)
            if func_names:
                for name in func_names:
                    self.remove_trace(name)

    def trace_decorator(self, func: Callable):
        """Decorator for function tracing"""
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            with self.with_trace([func.__name__]):
                return func(*args, **kwargs)
        return wrapper

# Global debugger instance
debugger = Tdb()

def example_traced_function(x, y):
    """Example function for demonstration"""
    result = x + y
    return result

# Usage example with decorator
@debugger.trace_decorator
def main():
    result = example_traced_function(10, 20)
    print(f"Result: {result}")

if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
from openerp import models, fields, api
from openerp.addons.decimal_precision as dp
from openerp.tools.translate import _
from openerp.tools import float_round

class PurchaseOrderLine(models.Model):
    _inherit = 'purchase.order.line'

    @api.depends('price_unit', 'order_id.currency_id', 'order_id.date_order')
    def _compute_prices_in_company_currency(self):
        for line in self:
            company_currency = line.company_id.currency_id
            order_currency = line.order_currency or line.order_id.currency_id
            date_order = line.order_id.date_order or fields.Date.today()

            # Currency conversion logic
            if order_currency and order_currency != company_currency:
                currency_rate = line.env['res.currency']._get_conversion_rate(
                    order_currency, company_currency, line.company_id, date_order
                )
                line.price_unit_co = line.price_unit * currency_rate
                line.price_subtotal_co = line.price_subtotal * currency_rate
            else:
                line.price_unit_co = line.price_unit
                line.price_subtotal_co = line.price_subtotal

    @api.depends('order_id', 'requisition_id')
    def _requisition_currency(self):
        for line in self:
            if line.requisition_id and line.requisition_id.currency_id:
                line.order_currency = line.requisition_id.currency_id
            else:
                line.order_currency = line.order_id.currency_id

    order_currency = fields.Many2one(
        'res.currency', 
        compute='_requisition_currency', 
        string='Order Currency',
        store=True
    )

    price_unit_co = fields.Float(
        string='Unit Price (Company Currency)',
        digits=dp.get_precision('Product Price'),
        compute='_compute_prices_in_company_currency',
        store=True
    )

    price_subtotal_co = fields.Float(
        string='Subtotal (Company Currency)',
        digits=dp.get_precision('Product Price'),
        compute='_compute_prices_in_company_currency',
        store=True
    )

    def _check_currency_consistency(self):
        """Validate currency consistency across purchase documents"""
        for line in self:
            if line.order_currency and line.requisition_id:
                if line.order_currency != line.requisition_id.currency_id:
                    raise ValueError(_(
                        "Currency mismatch between Purchase Order and Requisition"
                    ))

    @api.multi
    def write(self, vals):
        """Override write method to enforce currency validation"""
        result = super(PurchaseOrderLine, self).write(vals)
        self._check_currency_consistency()
        return result

    @api.model
    def create(self, vals):
        """Override create method to enforce currency validation"""
        line = super(PurchaseOrderLine, self).create(vals)
        line._check_currency_consistency()
        return line

