import math
import numpy as np

class GeometryUtils:
    @staticmethod
    def rotMatrix(axis, angle):
        """Generate rotation matrix from axis-angle representation."""
        x, y, z = axis
        c = math.cos(angle)
        s = math.sin(angle)
        t = 1 - c

        rotation_matrix = np.array([
            [t*x*x + c,     t*x*y - z*s,   t*x*z + y*s],
            [t*x*y + z*s,   t*y*y + c,     t*y*z - x*s],
            [t*x*z - y*s,   t*y*z + x*s,   t*z*z + c]
        ])

        return rotation_matrix

    @staticmethod
    def crossProduct(a, b):
        """Compute cross product between two vectors."""
        return np.array([
            a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0]
        ])

    @staticmethod
    def magnitude(vector):
        """Calculate vector magnitude."""
        return math.sqrt(np.dot(vector, vector))

    @staticmethod
    def normalise(vector):
        """Normalize vector to unit length."""
        mag = GeometryUtils.magnitude(vector)
        return vector / mag if mag != 0 else vector

    @staticmethod
    def pointNormal2Plane(point, normal):
        """Convert point and normal to plane equation."""
        d = -np.dot(point, normal)
        return np.append(normal, d)

    @staticmethod
    def plane2PointNormal(plane_equation):
        """Extract point and normal from plane equation."""
        normal = plane_equation[:3]
        d = plane_equation[3]
        point = -d * normal
        return point, normal

    @staticmethod
    def combineNormals(normals, weights=None):
        """Combine multiple surface normals with optional weighting."""
        if weights is None:
            weights = np.ones(len(normals))

        weighted_normals = [n * w for n, w in zip(normals, weights)]
        combined_normal = np.sum(weighted_normals, axis=0)
        return GeometryUtils.normalise(combined_normal)

    @staticmethod
    def coplanar(points, tolerance=1e-6):
        """Check if points are coplanar."""
        if len(points) <= 3:
            return True

        # Create vectors from first point
        vectors = [p - points[0] for p in points[1:]]

        # Compute cross products
        cross_products = []
        for i in range(len(vectors)):
            for j in range(i+1, len(vectors)):
                cross_products.append(
                    GeometryUtils.crossProduct(vectors[i], vectors[j])
                )

        # Check if cross products are nearly zero
        return all(
            GeometryUtils.magnitude(cp) < tolerance 
            for cp in cross_products
        )

    @staticmethod
    def transformVector(vector, matrix):
        """Apply transformation matrix to vector."""
        return np.dot(matrix, vector)

    @staticmethod
    def interpolateNormals(normal1, normal2, t):
        """Linearly interpolate between two normals."""
        interpolated = (1 - t) * normal1 + t * normal2
        return GeometryUtils.normalise(interpolated)

    @staticmethod
    def computePlaneIntersection(plane1, plane2, plane3):
        """Compute intersection point of three planes."""
        # Advanced plane intersection logic
        A = np.array([plane1[:3], plane2[:3], plane3[:3]])
        b = -np.array([plane1[3], plane2[3], plane3[3]])

        try:
            intersection_point = np.linalg.solve(A, b)
            return intersection_point
        except np.linalg.LinAlgError:
            return None

import re
from datetime import datetime

class DateFormatter:
    MONTH_NAMES = {
        1: 'Jan', 2: 'Feb', 3: 'Mar', 4: 'Apr', 
        5: 'May', 6: 'Jun', 7: 'Jul', 8: 'Aug', 
        9: 'Sep', 10: 'Oct', 11: 'Nov', 12: 'Dec'
    }

    @staticmethod
    def format_element(value):
        """
        Format individual elements with proper escaping
        """
        if not value:
            return ''
        return re.sub(r'([&<>"])', r'\\\1', str(value))

    @staticmethod
    def parse_date_components(date_str):
        """
        Parse date string into components
        """
        try:
            parsed_date = datetime.strptime(date_str, '%Y-%m-%d')
            return {
                'year': parsed_date.year,
                'month': parsed_date.month,
                'day': parsed_date.day
            }
        except (ValueError, TypeError):
            return {
                'year': None,
                'month': None,
                'day': None
            }

    def generate_date_range(self, start_date, end_date):
        """
        Generate formatted date range
        """
        start = self.parse_date_components(start_date)
        end = self.parse_date_components(end_date)

        # Complete date range
        if all([start['year'], start['month'], start['day'], 
                end['year'], end['month'], end['day']]):
            return self._format_complete_date_range(start, end)

        # Partial date range handling
        if start['year'] and end['year']:
            if start['year'] == end['year']:
                return f"{start['year']}"
            else:
                return f"{start['year']} - {end['year']}"

        return ''

    def _format_complete_date_range(self, start, end):
        """
        Format fully specified date ranges
        """
        if start['year'] == end['year'] and start['month'] == end['month']:
            # Same month range
            return (f"{self.MONTH_NAMES[start['month']]} "
                    f"{start['day']} - {end['day']}, {start['year']}")

        # Different months
        return (f"{self.MONTH_NAMES[start['month']]} {start['day']}, "
                f"{start['year']} - "
                f"{self.MONTH_NAMES[end['month']]} {end['day']}, {end['year']}")

    def process_bibliographic_dates(self, bfo):
        """
        Process dates from bibliographic object
        """
        start_date = bfo.get('job_start_date', '')
        end_date = bfo.get('job_end_date', '')

        formatted_dates = self.generate_date_range(start_date, end_date)

        return self.format_element(formatted_dates)

    def escape_values(self, value):
        """
        Escape special characters
        """
        return re.sub(r'([&<>"])', lambda m: f'\\{m.group(1)}', str(value))

    def create_full_address(self, bfo):
        """
        Create comprehensive address representation
        """
        address_components = [
            bfo.get('institution', ''),
            bfo.get('department', ''),
            bfo.get('city', ''),
            bfo.get('country', '')
        ]

        # Filter out empty components
        filtered_components = [comp for comp in address_components if comp]

        return ', '.join(filtered_components)

def main():
    # Example usage demonstration
    formatter = DateFormatter()

    # Simulated bibliographic object
    sample_bfo = {
        'job_start_date': '2020-06-15',
        'job_end_date': '2021-08-30',
        'institution': 'Research University',
        'department': 'Computer Science',
        'city': 'Boston',
        'country': 'USA'
    }

    formatted_dates = formatter.process_bibliographic_dates(sample_bfo)
    full_address = formatter.create_full_address(sample_bfo)

    print(f"Formatted Dates: {formatted_dates}")
    print(f"Full Address: {full_address}")

if __name__ == '__main__':
    main()

