class SnmpSession:
    def __init__(self, host, community='public'):
        self.host = host
        self.community = community

    def query(self, oid):
        try:
            result = subprocess.check_output(
                ['snmpget', '-v2c', '-c', self.community, self.host, oid],
                universal_newlines=True
            )
            return result.strip()
        except subprocess.CalledProcessError:
            return None

class NmapSession:
    def __init__(self, target, scan_type='quick'):
        self.target = target
        self.scan_type = scan_type
        self.output_file = f'scan_results_{target.replace("/", "_")}.xml'

    def perform_scan(self):
        scan_flags = '-sV -sC' if self.scan_type == 'full' else '-sn'
        try:
            subprocess.run([
                'nmap', scan_flags, 
                '-oX', self.output_file, 
                self.target
            ], check=True)
            return self.output_file
        except subprocess.CalledProcessError:
            return None

class Host:
