import threading
from typing import Any, Optional
from enum import Enum, auto

class PacketType(Enum):
    START = auto()
    STOP = auto()
    PAUSE = auto()
    NEXT = auto()
    PREV = auto()
    ENQUEUE = auto()
    LOAD = auto()
    SEEK = auto()
    EXIT = auto()

class ControlPacket:
    def __init__(self, packet_type: PacketType, data: Optional[Any] = None):
        self.__type = packet_type
        self.__data = data
        self.__lock = threading.Lock()
        self.__received_event = threading.Event()

    def getData(self) -> Optional[Any]:
        with self.__lock:
            return self.__data

    def getType(self) -> PacketType:
        return self.__type

    def wait(self, timeout: Optional[float] = None) -> bool:
        return self.__received_event.wait(timeout)

    def signal(self):
        self.__received_event.set()

class Start(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.START, data)

class Stop(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.STOP, data)

class Pause(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.PAUSE, data)

class Next(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.NEXT, data)

class Prev(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.PREV, data)

class Enqueue(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.ENQUEUE, data)

class Load(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.LOAD, data)

class Seek(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.SEEK, data)

class Exit(ControlPacket):
    def __init__(self, data: Optional[Any] = None):
        super().__init__(PacketType.EXIT, data)

class PacketDelay(ControlPacket):
    def __init__(self, delay: float, data: Optional[Any] = None):
        super().__init__(PacketType.SEEK, data)
        self.delay = delay

class PluginCommunicationManager:
    def __init__(self):
        self.__packet_queue = []
        self.__lock = threading.Lock()

    def sendPacket(self, packet: ControlPacket):
        with self.__lock:
            self.__packet_queue.append(packet)

    def handlePacket(self) -> Optional[ControlPacket]:
        with self.__lock:
            if self.__packet_queue:
                return self.__packet_queue.pop(0)
            return None

    def processPackets(self):
        while True:
            packet = self.handlePacket()
            if packet:
                packet.signal()
            threading.Event().wait(0.1)
